package com.inthehiggsfield.workerant.ui.theme

// GENERATED drawings for each theme's mascot (48x48 canvas, SVG path syntax).
// Colors: 1L-5L mean the theme's primary / secondary / tertiary / onBackground / background;
// anything else is a fixed 0xAARRGGBB color. Renderer: ThemeMascot.kt.

internal fun mascotFor(theme: AppTheme): List<MascotLayer> = when (theme) {
        AppTheme.Wallpaper, AppTheme.Grape, AppTheme.Forest, AppTheme.Ocean, AppTheme.Sunset -> mascotAnt()
